package com.yuegang.zhihui.training.application;
import com.fasterxml.jackson.databind.ObjectMapper;import com.yuegang.zhihui.common.core.*;import com.yuegang.zhihui.training.api.*;import java.math.*;import java.sql.*;import java.time.*;import java.util.*;import javax.sql.*;import org.springframework.jdbc.core.*;import org.springframework.transaction.annotation.*;
public final class TrainingAssignmentService{private final JdbcTemplate jdbc;private final ObjectMapper json;public TrainingAssignmentService(DataSource d,ObjectMapper j){jdbc=new JdbcTemplate(d);json=j;}@Transactional public AssignmentView assign(long operator,CreateAssignmentRequest c){long id=System.currentTimeMillis()*1000+Math.floorMod((c.userId()+c.courseId()).hashCode(),1000);Long path=c.pathId()==null||c.pathId().isBlank()?null:positive(c.pathId());long user=positive(c.userId()),course=positive(c.courseId());int inserted=jdbc.update("INSERT INTO training_assignment(id,user_id,path_id,course_id,assigned_by,due_at) SELECT ?,?,?,?,?,? WHERE EXISTS(SELECT 1 FROM training_course WHERE id=? AND status='PUBLISHED')",id,user,path,course,operator,c.dueAt()==null?null:Timestamp.from(c.dueAt().toInstant()),course);if(inserted!=1)throw new BusinessException(ErrorCode.BUSINESS_CONFLICT);String title=jdbc.queryForObject("SELECT title FROM training_course WHERE id=?",String.class,course);String event="training-assigned-"+id;jdbc.update("INSERT INTO training_outbox(id,aggregate_id,event_type,payload_json) VALUES(?,?,?,?)",event,Long.toString(id),"TRAINING_ASSIGNED",write(Map.of("assignmentId",Long.toString(id),"userId",Long.toString(user),"courseId",Long.toString(course),"courseTitle",title==null?"":title)));return find(id);}public List<AssignmentView>mine(long user){return jdbc.query("SELECT id,user_id,course_id,status,due_at FROM training_assignment WHERE user_id=? ORDER BY assigned_at DESC",(r,n)->map(r),user);}public TrainingStatisticsView statistics(){return jdbc.query("SELECT COUNT(*) assigned,SUM(status='IN_PROGRESS') progressing,SUM(status='COMPLETED') completed,SUM(status<>'COMPLETED' AND due_at<NOW(6)) overdue FROM training_assignment",r->{if(!r.next())return new TrainingStatisticsView(0,0,0,0,BigDecimal.ZERO);long assigned=r.getLong("assigned"),completed=r.getLong("completed");BigDecimal rate=assigned==0?BigDecimal.ZERO:BigDecimal.valueOf(completed*100).divide(BigDecimal.valueOf(assigned),2,RoundingMode.HALF_UP);return new TrainingStatisticsView(assigned,r.getLong("progressing"),completed,r.getLong("overdue"),rate);});}private AssignmentView find(long id){return jdbc.query("SELECT id,user_id,course_id,status,due_at FROM training_assignment WHERE id=?",r->{if(!r.next())throw new BusinessException(ErrorCode.BUSINESS_CONFLICT);return map(r);},id);}private String write(Object x){try{return json.writeValueAsString(x);}catch(Exception e){throw new IllegalStateException(e);}}private static AssignmentView map(java.sql.ResultSet r)throws java.sql.SQLException{Timestamp due=r.getTimestamp("due_at");return new AssignmentView(Long.toString(r.getLong("id")),Long.toString(r.getLong("user_id")),Long.toString(r.getLong("course_id")),r.getString("status"),due==null?null:due.toInstant().atOffset(ZoneOffset.UTC));}private static long positive(String value){try{long id=Long.parseLong(value);if(id<=0)throw new NumberFormatException();return id;}catch(NumberFormatException e){throw new BusinessException(ErrorCode.VALIDATION_ERROR);}}}
